def parse_domain_answer(answer, *, initial=False):
    text = answer.strip().removeprefix('```json').removesuffix('```').strip()
    try:
        return json.loads(text), False
    except json.JSONDecodeError as exc:
        # A premature close of the root followed by more object members has
        # one local repair: remove that close. Keep every field and value.
        if not initial or exc.msg != 'Extra data' or text[exc.pos:exc.pos+1] != ',':
            raise
        prefix = text[:exc.pos].rstrip()
        if not prefix.startswith('{') or not prefix.endswith('}'):
            raise
        def unique_object(pairs):
            result = dict(pairs)
            if len(result) != len(pairs):
                raise ValueError('Cannot recover an object with duplicate keys')
            return result
        return json.loads(prefix[:-1] + text[exc.pos:], object_pairs_hook=unique_object), True


