"""Deterministic requirement ingestion. Evaluation code is not model input."""

import base64
import json
import mimetypes
import re
from pathlib import Path

import yaml

TEXT = {'.md', '.txt', '.yaml', '.yml', '.json', '.csv', '.tsv', '.sql'}
IMAGES = {'.png', '.jpg', '.jpeg', '.webp', '.gif'}
EXCLUDE = {'tests', 'test', 'test-e2e', 'eval', 'evaluation', 'evaluations',
           'node_modules', 'playwright-report', 'test-results', '__pycache__'}
ASSET_MAX_BYTES = 32 * 1024 * 1024
MAX_FILE_COUNT = 500


class InputError(ValueError):
    pass


class RequirementLoader(yaml.SafeLoader):
    # PyYAML defaults to YAML 1.1 booleans (e.g. labels `Yes` and `On`).
    yaml_implicit_resolvers = {
        char: [(tag, pattern) for tag, pattern in resolvers
               if tag not in {'tag:yaml.org,2002:bool', 'tag:yaml.org,2002:timestamp'}]
        for char, resolvers in yaml.SafeLoader.yaml_implicit_resolvers.items()
    }


RequirementLoader.add_implicit_resolver('tag:yaml.org,2002:bool', re.compile(r'^(true|false)$', re.I), 'tTfF')


def compact(value):
    # Only omit known empty structural lists; extras may use null or empty values.
    if isinstance(value, dict):
        return {str(k): compact(v) for k, v in value.items()
                if k not in {'children', 'scenarios', 'dependencies'} or v != []}
    if isinstance(value, list):
        return [compact(v) for v in value]
    return value


def render_legacy_markdown(root):
    """Recognize the platform's alternate Markdown view, never approximate its prose."""
    if not isinstance(root, dict):
        return ''
    lines = []

    def visit(node, depth):
        if not isinstance(node, dict) or not isinstance(node.get('description', ''), str):
            raise ValueError
        title = str(node.get('name', '')) if depth == 0 else f"{node.get('id', '')} {node.get('name', '')}"
        lines.extend(['#' * (depth + 1) + ' ' + title, node.get('description', '')])
        if depth:
            lines.extend([f"**Type:** {node.get('type', '')}",
                          '**Dependencies:** ' + (', '.join(node.get('dependencies', [])) or 'None')])
        if node.get('scenarios'):
            lines.append('**Scenarios:**')
            for scenario in node['scenarios']:
                lines.append('- ' + scenario['name'])
                for step in scenario['steps']:
                    lines.append(f"  - **{step['keyword']}:** {step['content']}")
        for child in node.get('children', []):
            visit(child, depth + 1)

    try:
        visit(root, 0)
    except (KeyError, TypeError, ValueError):
        return ''
    return '\n'.join(lines)


def render_structured_markdown(root):
    """Reconstruct the Markdown projection of structured requirement trees."""
    blocks = []

    def visit(node, depth):
        title = node['name'] if depth == 0 else f"{node['id']} {node['name']}"
        description = node['description']
        children = node.get('children', [])
        blocks.extend(['#' * (depth + 1) + ' ' + title, description['text']])
        for image in description.get('image', []):
            label = f"{image['id']} · {image['page']}"
            blocks.extend([f"**{label}**", f"![{label}]({image['reference']})"])
        if depth:
            kind = node.get('type', 'FOLDER' if children else 'ATOMIC')
            deps = ', '.join(node.get('dependencies', [])) or 'None'
            blocks.append(f"**Type:** {kind}\n**Dependencies:** {deps}")
        scenarios = node.get('scenarios', [])
        if scenarios:
            blocks.append('**Scenarios:**')
        rows = []
        for scenario in scenarios:
            lines = [f"- {scenario['id']} — {scenario['name']}"]
            for step in scenario['steps']:
                lines.append(f"  - **Step:** {step['id']}")
                for phase in ('Given', 'When', 'Then', 'And', 'But'):
                    if phase not in step:
                        continue
                    first, *rest = step[phase].split('\n')
                    lines.append(f"    - **{phase}:** {first}")
                    lines.extend('      ' + line if line else '' for line in rest)
                if step.get('references'):
                    refs = ', '.join(f"`{ref}`" for ref in step['references'])
                    lines.append(f"    - **References:** {refs}")
            rows.extend(lines)
        if rows:
            blocks.append('\n'.join(rows))
        for child in children:
            visit(child, depth + 1)

    try:
        visit(root, 0)
    except (AttributeError, KeyError, TypeError, ValueError):
        return ''
    return '\n\n'.join(blocks)


def is_yaml_mirror(markdown, root):
    # The structured view must match the reconstruction line by line. A
    # Markdown-only paragraph, image, condition or altered value stays input.
    structured = render_structured_markdown(root)
    normalize_lines = lambda value: '\n'.join(line.rstrip() for line in value.strip().splitlines())
    if structured and normalize_lines(markdown) == normalize_lines(structured):
        return True
    mirror = render_legacy_markdown(root)
    # Only whitespace is normalized; a changed label, condition or added paragraph
    # makes this comparison fail, keeping the entire Markdown in the model input.
    return bool(mirror) and ' '.join(markdown.split()) == ' '.join(mirror.split())


def discover(root):
    pending = [root]
    files = []
    while pending:
        for path in sorted(pending.pop().iterdir()):
            name = path.name.lower()
            if (name.startswith('.') or name in EXCLUDE or path.is_symlink()
                    or getattr(path, 'is_junction', lambda: False)()
                    or re.search(r'\.(?:spec|test)\.', name)):
                continue
            if path.is_dir():
                pending.append(path)
            elif path.is_file():
                files.append(path)
                if len(files) > MAX_FILE_COUNT:
                    raise InputError(f'Input contains more than {MAX_FILE_COUNT} eligible files')
    return sorted(files)


def read_text(path, limit):
    with path.open('rb') as handle:
        data = handle.read(limit * 4 + 4)
    if len(data) > limit * 4 + 3:
        raise InputError(f'Input character limit exceeded while reading {path.name}')
    result = data.decode('utf-8-sig')
    if len(result) > limit:
        raise InputError(f'Input character limit exceeded while reading {path.name}')
    return result


def load(root: Path, max_chars: int):
    if not root.is_dir():
        raise InputError('Requirement input must be a directory')
    files = discover(root)
    spec = root / 'requirements.yaml'
    if spec not in files:
        raise InputError('Input has no regular requirements.yaml')
    # Allow whitespace-heavy YAML to compact before charging it against the prompt.
    try:
        raw = yaml.load(read_text(spec, max_chars * 4), Loader=RequirementLoader)
        if not isinstance(raw, (dict, list)) or not raw:
            raise InputError('requirements.yaml must contain a nonempty mapping or list')
        tree = json.dumps(compact(raw), ensure_ascii=False, separators=(',', ':'), default=str)
    except (yaml.YAMLError, RecursionError) as exc:
        raise InputError('Invalid or recursive requirements.yaml') from exc
    sections = ['REQUIREMENTS YAML (compact JSON)\n' + tree]
    assets, images, listed = [], [], []
    asset_bytes = 0
    used = len(sections[0])
    seen = set()
    for path in files:
        if path == spec:
            continue
        relative = path.relative_to(root)
        suffix = path.suffix.lower()
        if relative.parts[0] == 'assets' and len(relative.parts) > 1:
            asset_bytes += path.stat().st_size
            if asset_bytes > ASSET_MAX_BYTES:
                raise InputError('assets/ exceeds 32 MiB')
            assets.append(relative)
        if suffix in IMAGES:
            images.append(relative)
        if suffix in TEXT:
            content = read_text(path, max_chars).strip()
            if relative.as_posix() == 'requirements.md' and is_yaml_mirror(content, raw):
                continue
            # Only deduplicate exact copies. Descriptions, scenarios and extras are preserved.
            if content and content not in seen:
                seen.add(content)
                section = f'MATERIAL {relative.as_posix()}\n{content}'
                used += len(section) + 2
                if used > max_chars:
                    raise InputError(f'Combined input exceeds --input-chars at {relative.as_posix()}')
                sections.append(section)
        elif suffix in IMAGES or relative in assets:
            listed.append(relative.as_posix())
    # Sort against the source, before the inventory makes every name appear referenced.
    source_text = '\n\n'.join(sections).replace('\\\\', '/')
    positions = {path: source_text.find(path.as_posix()) for path in images}
    images.sort(key=lambda path: (positions[path] < 0, positions[path], path.as_posix()))
    if listed:
        sections.append('FILE INVENTORY (only assets/ is served in the app)\n' + '\n'.join(listed))
    text = '\n\n'.join(sections)
    if len(text) > max_chars:
        raise InputError('Combined input exceeds --input-chars')
    return text, assets, images


def message_with_images(text, root, images, limit):
    content = [{'type': 'text', 'text': text}]
    count = 0
    for relative in images:
        if count >= limit:
            break
        path = root / relative
        if path.stat().st_size > 2 * 1024 * 1024:
            continue
        mime = mimetypes.guess_type(path)[0]
        data = base64.b64encode(path.read_bytes()).decode('ascii')
        content.extend([
            {'type': 'text', 'text': f'Reference image: {relative.as_posix()}'},
            {'type': 'image_url', 'image_url': {'url': f'data:{mime};base64,{data}'}},
        ])
        count += 1
    return content if count else text, count
